describe('Modal Form Submission', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
  });

  it('should successfully submit form in modal and display success message', () => {
    cy.get('[data-testid="modal-form"]').within(() => {
      cy.get('input[name="firstName"]').type('John');
      cy.get('input[name="lastName"]').type('Doe');
      cy.get('input[name="email"]').type('john.doe@example.com');
      cy.get('textarea[name="message"]').type('This is a test message');
      cy.get('button[type="submit"]').click();
    });

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
    cy.get('[data-testid="success-icon"]').should('exist');
  });

  it('should display validation errors when submitting empty form', () => {
    cy.get('[data-testid="modal-form"]').within(() => {
      cy.get('button[type="submit"]').click();
    });

    cy.get('[data-testid="error-firstName"]').should('be.visible');
    cy.get('[data-testid="error-firstName"]').should('contain', 'First name is required');
    cy.get('[data-testid="error-email"]').should('be.visible');
    cy.get('[data-testid="error-email"]').should('contain', 'Email is required');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });

  it('should close modal after successful submission', () => {
    cy.get('[data-testid="modal-form"]').within(() => {
      cy.get('input[name="firstName"]').type('Jane');
      cy.get('input[name="lastName"]').type('Smith');
      cy.get('input[name="email"]').type('jane.smith@example.com');
      cy.get('button[type="submit"]').click();
    });

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.be.visible');
  });

  it('should handle form submission with special characters and long text', () => {
    cy.get('[data-testid="modal-form"]').within(() => {
      cy.get('input[name="firstName"]').type("O'Brien");
      cy.get('input[name="lastName"]').type('Müller-García');
      cy.get('input[name="email"]').type('test+special@example.co.uk');
      cy.get('textarea[name="message"]').type('This is a very long message with special characters: !@#$%^&*()_+-=[]{}|;:,.<>?');
      cy.get('button[type="submit"]').click();
    });

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should display error for invalid email format', () => {
    cy.get('[data-testid="modal-form"]').within(() => {
      cy.get('input[name="firstName"]').type('John');
      cy.get('input[name="lastName"]').type('Doe');
      cy.get('input[name="email"]').type('invalid-email-format');
      cy.get('button[type="submit"]').click();
    });

    cy.get('[data-testid="error-email"]').should('be.visible');
    cy.get('[data-testid="error-email"]').should('contain', 'Please enter a valid email');
    cy.get('[data-testid="success-message"]').should('not.exist');
  });

  it('should allow form reset and resubmission', () => {
    cy.get('[data-testid="modal-form"]').within(() => {
      cy.get('input[name="firstName"]').type('Initial');
      cy.get('button[type="reset"]').click();
      cy.get('input[name="firstName"]').should('have.value', '');

      cy.get('input[name="firstName"]').type('John');
      cy.get('input[name="lastName"]').type('Doe');
      cy.get('input[name="email"]').type('john@example.com');
      cy.get('button[type="submit"]').click();
    });

    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
